"""Independent reference implementation used only for testing."""
import itertools
from fractions import Fraction

G = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))


def canon(a, b):
    return (a, b) if a < b else (b, a)


def normalize(path, ixps):
    out = []
    for a in path:
        if a in ixps:
            continue
        if out and out[-1] == a:
            continue
        out.append(a)
    return out


def aggregate(rib, ixps):
    cur = {}
    for p, c in rib:
        q = normalize(p, ixps)
        if len(q) < 2 or len(set(q)) != len(q):
            continue
        t = tuple(q)
        cur[t] = cur.get(t, 0) + c
    return cur


def peel_naive(agg):
    """Recompute the peripheral marking from scratch every round."""
    cur = dict(agg)
    all_links = set()
    for p in cur:
        for i in range(len(p) - 1):
            all_links.add(canon(p[i], p[i + 1]))
    rounds = {}
    r = 0
    while True:
        plist = list(cur.keys())
        containing = {}
        for p in plist:
            for i in range(len(p) - 1):
                containing.setdefault(canon(p[i], p[i + 1]), []).append(p)
        marked = set()
        for link, ps in containing.items():
            u, v = link
            if all(p[0] == u or p[-1] == u for p in ps):
                marked.add(link)
            elif all(p[0] == v or p[-1] == v for p in ps):
                marked.add(link)
        if not marked:
            break
        r += 1
        for link in marked:
            rounds[link] = r
        new = {}
        for p, c in cur.items():
            df = canon(p[0], p[1]) in marked
            dl = canon(p[-2], p[-1]) in marked
            q = p[(1 if df else 0):(len(p) - (1 if dl else 0))]
            if len(q) >= 2:
                new[q] = new.get(q, 0) + c
        cur = new
    return all_links, rounds, cur


def inv(t):
    return 2 - t if t in (0, 2) else 1


def occurrences(final_paths, core_links):
    vi = {e: i for i, e in enumerate(core_links)}
    occ = [[] for _ in core_links]
    for p, c in final_paths.items():
        n = len(p)
        for seq in (p, p[::-1]):
            for j in range(n - 1):
                if seq[j] >= seq[j + 1]:
                    continue
                ev = vi[(seq[j], seq[j + 1])]
                if j == 0:
                    lk = ('c', 0)
                else:
                    x, y = seq[j - 1], seq[j]
                    lk = ('v', vi[canon(x, y)], 0 if x < y else 1)
                if j + 2 >= n:
                    rk = ('c', 2)
                else:
                    x, y = seq[j + 1], seq[j + 2]
                    rk = ('v', vi[canon(x, y)], 0 if x < y else 1)
                occ[ev].append((c, lk, rk))
    return occ


def ctx(kind, X):
    if kind[0] == 'c':
        return kind[1]
    t = X[kind[1]]
    return t if kind[2] == 0 else inv(t)


def brute(occ):
    """Exact joint by enumeration of all assignments."""
    m = len(occ)
    phi = []
    for e in range(m):
        col = [0, 0, 0]
        for (c, lk, rk) in occ[e]:
            for t in range(3):
                pass
            col[0] = col[1] = col[2] = 0
        phi.append(None)
    Z = 0
    marg = [[0, 0, 0] for _ in range(m)]
    for X in itertools.product(range(3), repeat=m):
        w = 1
        for e in range(m):
            s = 0
            for (c, lk, rk) in occ[e]:
                L = ctx(lk, X)
                R = ctx(rk, X)
                if X[e] == G[L][R]:
                    s += c
            if s:
                w *= s
            else:
                w = 0
                break
        if w:
            Z += w
            for e in range(m):
                marg[e][X[e]] += w
    return Z, marg


def full_dp(vectors):
    up, peer, down = 1.0, 0.0, 0.0
    for vec in vectors:
        a, b, c = float(vec[0]), float(vec[1]), float(vec[2])
        up, peer, down = up * a, up * b, (up + peer + down) * c
    return up + peer + down


def reference(doc):
    ixps = set(doc['ixps'])
    agg = aggregate([(tuple(r['path']), r['count']) for r in doc['rib']], ixps)
    all_links, rounds, final = peel_naive(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(canon(p[i], p[i + 1]))
    core_list = sorted(core)
    if core_list:
        occ = occurrences(final, core_list)
        Z, marg = brute(occ)
        if Z == 0:
            return {'error': 'zero-partition'}
        core_prob = {}
        for i, e in enumerate(core_list):
            core_prob[e] = tuple(Fraction(marg[i][t], Z) for t in range(3))
    else:
        core_prob = {}

    priors = {}
    for rec in doc['priors']:
        u, v = rec['link']
        w = rec['weights']
        s = sum(w)
        vec = tuple(Fraction(x, s) for x in w)
        key = canon(u, v)
        if u > v:
            vec = (vec[2], vec[1], vec[0])
        priors[key] = vec
    declared = {}
    for rec in doc['declared']:
        u, v = rec['link']
        onehot = [0, 0, 0]
        onehot[['c2p', 'p2p', 'p2c'].index(rec['rel'])] = 1
        vec = tuple(onehot)
        if u > v:
            vec = (vec[2], vec[1], vec[0])
        declared[canon(u, v)] = vec

    links = []
    for e in sorted(all_links):
        if e in core:
            links.append({'link': list(e), 'round': 0,
                          'prob': [float(x) for x in core_prob[e]]})
        else:
            vec = priors.get(e, UNIFORM)
            links.append({'link': list(e), 'round': rounds[e],
                          'prob': [float(x) for x in vec]})

    queries = []
    for rec in doc['queries']:
        p = normalize(rec['path'], ixps)
        a, b = rec['threshold']
        if len(set(p)) != len(p):
            queries.append({'id': rec['id'], 'path': list(p), 'status': 'loop',
                            'score': None, 'full': None, 'witness': None,
                            'leaked': None})
            continue
        vectors = []
        for i in range(len(p) - 1):
            u, v = p[i], p[i + 1]
            key = canon(u, v)
            if key in declared:
                base = declared[key]
            elif key in core_prob:
                base = core_prob[key]
            elif key in priors:
                base = priors[key]
            else:
                base = UNIFORM
            vectors.append(base if u < v else (base[2], base[1], base[0]))
        if len(vectors) < 2:
            score, witness, full = Fraction(1), None, 1.0
        else:
            triples = [vectors[i][0] + vectors[i + 1][2] - vectors[i][0] * vectors[i + 1][2]
                       for i in range(len(vectors) - 1)]
            score = min(triples)
            witness = triples.index(score)
            full = full_dp(vectors)
        queries.append({'id': rec['id'], 'path': list(p), 'status': 'ok',
                        'score': float(score), 'full': float(full),
                        'witness': witness, 'leaked': score < Fraction(a, b)})
    return {'version': 1, 'links': links, 'queries': queries}
